      throw error;
    }
  }

  /**
   * 查询表单数据
   */
  async queryFormData(formUuid, queryConditions) {
    try {
      const token = await this.getAccessToken();
      const response = await fetch(`${this.baseUrl}/yida/form/data/query?access_token=${token}`, {
        method: 'POST',
